    [Fact]
    public void AC4_LibraryDeclaredKeysWithoutMessagePackDependencyAreHonored()
    {
        // Project A (no MessagePack reference) describes integer keys, declared in reverse order of the members.
        // Two mechanisms from the requirement are tried independently; either being honored satisfies the probe:
        //  (option 2) user-declared internal copies of the MessagePack attributes,
        //  (option 1) BCL DataContract/DataMember(Order).
        string dummyAttributesLibrary = """
namespace MessagePack
{
    [System.AttributeUsage(System.AttributeTargets.Class | System.AttributeTargets.Struct)]
    internal sealed class MessagePackObjectAttribute : System.Attribute
    {
        public MessagePackObjectAttribute(bool keyAsPropertyName = false) { }
    }

    [System.AttributeUsage(System.AttributeTargets.Property | System.AttributeTargets.Field)]
    internal sealed class KeyAttribute : System.Attribute
    {
        public KeyAttribute(int x) { }
        public KeyAttribute(string x) { }
    }
}

namespace ProjectA
{
    [MessagePack.MessagePackObject]
    public class MyObject
    {
        [MessagePack.Key(1)]
        public string? Label { get; set; }

        [MessagePack.Key(0)]
        public int Id { get; set; }
    }
}
""";

        string consumer = """
using MessagePack.Formatters;

[MessagePack.GeneratedMessagePackFormatter]
public partial class MyObjectFormatter : IMessagePackFormatter<ProjectA.MyObject>
{
}
""" + RoundtripHelper;

        // Array of 2: [42, "hello"] => 92 2A A5 68656C6C6F
        const string expected = "42|hello|922AA568656C6C6F";
        List<string> outcomes = new();
        foreach (var (name, library) in new[] { ("DummyMessagePackAttributes", dummyAttributesLibrary), ("DataMember", Ac4DataMemberLibrary) })
        {
            try
            {
                var (libImage, libRef) = BuildLibrary(library);
                byte[] image = BuildConsumer(consumer, libRef);
                string result = (string)Invoke(libImage, image, "Probe", "Run")!;
                if (result == expected)
                {
                    return;
                }

                outcomes.Add($"{name}: got '{result}', expected '{expected}'");
            }
            catch (Exception ex)
            {
                outcomes.Add($"{name}: {ex.Message}");
            }
        }

        Assert.Fail("No library-side key mechanism was honored:\n" + string.Join("\n", outcomes));
    }

