public static class Probe
{
    public static string Run()
    {
        var options = MessagePack.MessagePackSerializerOptions.Standard.WithResolver(
            MessagePack.Resolvers.CompositeResolver.Create(MessagePack.GeneratedMessagePackResolver.Instance, MessagePack.Resolvers.StandardResolver.Instance));
        var original = new ProjectA.MyObject { Id = 42, Label = "hello" };
        byte[] bytes = MessagePack.MessagePackSerializer.Serialize(original, options);
        var copy = MessagePack.MessagePackSerializer.Deserialize<ProjectA.MyObject>(bytes, options);
        return copy.Id + "|" + copy.Label + "|" + System.Convert.ToHexString(bytes)
            + "|" + (MessagePack.GeneratedMessagePackResolver.Instance.GetFormatter<ProjectA.MyObject>() is not null);
    }
}
""";

        byte[] image = BuildConsumer(consumer, library: null);
        string result = (string)Invoke(null, image, "Probe", "Run")!;
        Assert.Equal("42|hello|922AA568656C6C6F|True", result);
    }

