    [Fact]
    public async Task DataMemberOrderOnExternalTypeIsHonored()
    {
        ImmutableArray<MetadataReference> refs = await ReferenceAssemblies.Net.Net80.ResolveAsync(LanguageNames.CSharp, CancellationToken.None);
        List<MetadataReference> allRefs = refs.Concat(ReferencesHelper.GetReferences(ReferencesSet.MessagePack)).ToList();

        // Project A: declares the type, no MessagePack dependency, uses DataMember to describe keys.
        string projectA = """
            using System.Runtime.Serialization;
            namespace ExternalLib
            {
                [DataContract]
                public class ExternalPerson
                {
                    [DataMember(Order = 0)]
                    public int Id { get; set; }

                    [DataMember(Order = 1)]
                    public string Name { get; set; }
                }
            }
            """;
        CSharpCompilation compA = CSharpCompilation.Create(
            "ExternalLib",
            new[] { CSharpSyntaxTree.ParseText(projectA) },
            refs,
            new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));
        using MemoryStream ms = new();
        var emit = compA.Emit(ms);
        Assert.True(emit.Success, string.Join("\n", emit.Diagnostics));
        MetadataReference refA = MetadataReference.CreateFromImage(ms.ToArray());

        // Project B: consumer.
        string projectB = """
            using MessagePack;
            using MessagePack.Formatters;
            using ExternalLib;

            [GeneratedMessagePackFormatter]
            public partial class F : IMessagePackFormatter<ExternalPerson>
            {
            }

            [GeneratedMessagePackResolver]
            partial class MyResolver { }
            """;
        CSharpCompilation compB = CSharpCompilation.Create(
            "Consumer",
            new[] { CSharpSyntaxTree.ParseText(projectB, new CSharpParseOptions(LanguageVersion.Latest)) },
            allRefs.Append(refA),
            new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));

        GeneratorDriver driver = CSharpGeneratorDriver.Create(new MessagePack.SourceGenerator.MessagePackGenerator())
            .WithUpdatedParseOptions(new CSharpParseOptions(LanguageVersion.Latest));
        driver = driver.RunGenerators(compB);
        GeneratorDriverRunResult result = driver.GetRunResult();

        string formatterSource = string.Join(
            "\n",
            result.GeneratedTrees.Select(t => t.GetText().ToString()).Where(s => s.Contains("ExternalPerson") && s.Contains("Serialize(")));
        this.output.WriteLine(formatterSource);
        Assert.False(string.IsNullOrEmpty(formatterSource), "No formatter generated for ExternalPerson");

        // Expected per AC4: DataMember(Order) on the declaring type defines integer keys => array of 2.
        Assert.Contains("WriteArrayHeader(2)", formatterSource);
        Assert.DoesNotContain("WriteMapHeader", formatterSource);
    }
}

