using System.Collections.Immutable;
using MessagePack.SourceGenerator;
using MessagePack.SourceGenerator.Analyzers;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.Diagnostics;

public class CountersignFinding3
{
    private readonly ITestOutputHelper logger;

    public CountersignFinding3(ITestOutputHelper logger)
    {
        this.logger = logger;
    }

    [Fact]
    public async Task TwoGeneratedFormattersForSameType_BothGeneratedOrDiagnosed()
    {
        string source = """
            using MessagePack;
            using MessagePack.Formatters;

            namespace N
            {
                public class Ext
                {
                    public int Id { get; set; }
                }

                public class S
                {
                    [Key(0)]
                    public int Id { get; set; }
                }

                [GeneratedMessagePackFormatter]
                public partial class AFormatter : IMessagePackFormatter<Ext>
                {
                }

                [GeneratedMessagePackFormatter(SurrogateType = typeof(S))]
                public partial class BFormatter : IMessagePackFormatter<Ext>
                {
                }

                [GeneratedMessagePackResolver]
                partial class MyResolver { }
            }
            """;

        ImmutableArray<MetadataReference> refs = await ReferencesHelper.DefaultTargetFrameworkReferences.ResolveAsync(LanguageNames.CSharp, CancellationToken.None);
        CSharpCompilation compilation = CSharpCompilation.Create(
            "TestAsm",
            new[] { CSharpSyntaxTree.ParseText(source, new CSharpParseOptions(LanguageVersion.CSharp7_3)) },
            refs.Concat(ReferencesHelper.GetReferences(ReferencesSet.MessagePack)),
            new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));

        GeneratorDriver driver = CSharpGeneratorDriver.Create(new[] { new MessagePackGenerator().AsSourceGenerator() }, parseOptions: new CSharpParseOptions(LanguageVersion.CSharp7_3));
        driver = driver.RunGeneratorsAndUpdateCompilation(compilation, out Compilation output, out ImmutableArray<Diagnostic> genDiags);

        ImmutableArray<DiagnosticAnalyzer> analyzers = typeof(MsgPack001SpecifyOptionsAnalyzer).Assembly.GetTypes()
            .Where(t => typeof(DiagnosticAnalyzer).IsAssignableFrom(t) && !t.IsAbstract)
            .Select(t => (DiagnosticAnalyzer)Activator.CreateInstance(t)!)
            .ToImmutableArray();
        ImmutableArray<Diagnostic> all = await output.WithAnalyzers(analyzers).GetAllDiagnosticsAsync();
        all = all.AddRange(genDiags);

        foreach (Diagnostic d in all)
        {
            this.logger.WriteLine(d.ToString());
        }

        foreach (SyntaxTree tree in output.SyntaxTrees.Skip(1))
        {
            this.logger.WriteLine("=== " + tree.FilePath);
        }

        bool hasCs0535 = all.Any(d => d.Id == "CS0535");
        bool hasMsgPackDiag = all.Any(d => d.Id.StartsWith("MsgPack", StringComparison.Ordinal) && d.Severity >= DiagnosticSeverity.Warning);

        // Correct behaviour: either both formatters get bodies (no CS0535), or a MsgPack diagnostic explains the conflict.
        Assert.True(!hasCs0535 || hasMsgPackDiag, "CS0535 reported for a [GeneratedMessagePackFormatter] class without any MsgPack diagnostic:\n" + string.Join("\n", all.Select(d => d.ToString())));
    }

